import React, { useEffect, useRef, useState } from 'react';
import { Box, Typography } from '@mui/material';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import MoonCanvas from '../features/ramadan/MoonCanvas';
import { moonPhase, moonIllumination, moonPhaseKey, pad2, useRamadanCountdown, FIRST_NIGHT } from '../features/ramadan/ramadanSeason';
import { subscribeToNewsletter } from '../services/newsletterService';

// /ramadan: the countdown to Ramadan 1448 under tonight's real moon, thirty lanterns
// for thirty nights, the app's Ramadan features in three waves, and a reminder sign-up
// (newsletter topic "ramadan", sent from /admin/newsletter when the moon is sighted).
const C = {
    sky: '#060A1F', sky2: '#0D1638', gold: '#E8C46A', goldHi: '#FFF0C2', ivory: '#F4ECDC', mist: '#A9B0CC',
    line: 'rgba(232,196,106,.22)', panel: 'rgba(13,22,56,.55)',
};
const DISPLAY = '"Marcellus", "Iowan Old Style", Georgia, serif';
const ARABIC = '"Amiri", "Geeza Pro", serif';
const reduceMotion = () => typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

const Eyebrow = ({ children }) => (
    <Typography sx={{ fontSize: 12, letterSpacing: '.24em', 'html[dir="rtl"] &': { letterSpacing: 0 }, textTransform: 'uppercase', color: C.gold, fontWeight: 600 }}>{children}</Typography>
);
const H2 = ({ children, id }) => (
    <Typography id={id} component="h2" sx={{ fontFamily: DISPLAY, fontSize: { xs: 32, md: 46 }, lineHeight: 1.1, textWrap: 'balance', color: C.ivory }}>{children}</Typography>
);
const Ar = ({ children, sx }) => <Box component="p" lang="ar" dir="rtl" sx={{ fontFamily: ARABIC, color: C.gold, m: 0, ...sx }}>{children}</Box>;
const Section = ({ children, ...rest }) => (
    <Box component="section" {...rest} sx={{ maxWidth: 1080, mx: 'auto', px: 'max(16px, env(safe-area-inset-left, 0px))', py: { xs: 6, md: 8 }, position: 'relative' }}>{children}</Box>
);

// Twinkling stars behind the whole page.
function Stars({ warm }) {
    const ref = useRef(null);
    useEffect(() => {
        const el = ref.current; if (!el) return undefined;
        const ctx = el.getContext('2d'); const still = reduceMotion();
        let stars = [], raf = 0, W = 0, H = 0;
        const size = () => {
            const dpr = Math.min(window.devicePixelRatio || 1, 2); W = el.clientWidth; H = el.clientHeight;
            el.width = W * dpr; el.height = H * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            stars = Array.from({ length: Math.min(900, Math.round((W * H) / 5200)) }, () => ({ x: Math.random() * W, y: Math.random() * H, r: Math.random() * 1.2 + 0.2, p: Math.random() * 6.28, s: 0.4 + Math.random() }));
        };
        const draw = (t) => {
            ctx.clearRect(0, 0, W, H);
            for (const s of stars) {
                ctx.globalAlpha = 0.35 + 0.5 * (still ? 0.6 : Math.sin((t / 1000) * s.s + s.p) * 0.5 + 0.5);
                ctx.fillStyle = '#FFF6DC'; ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, 6.283); ctx.fill();
            }
            ctx.globalAlpha = 1;
            if (!still) raf = requestAnimationFrame(draw);
        };
        size(); draw(0);
        const ro = new ResizeObserver(() => { size(); if (still) draw(0); }); ro.observe(el);
        return () => { cancelAnimationFrame(raf); ro.disconnect(); };
    }, []);
    return (
        <Box aria-hidden sx={{ position: 'absolute', inset: 0, transition: 'background 1.2s',
            background: `linear-gradient(180deg, ${C.sky} 0%, ${C.sky2} 60%, ${warm ? '#3A2550' : '#1A1640'} 100%)` }}>
            <Box component="canvas" ref={ref} sx={{ position: 'sticky', top: 0, width: '100%', height: '100vh', display: 'block' }} />
        </Box>
    );
}

function Countdown({ count, t }) {
    const units = count ? [count.days, pad2(count.hours), pad2(count.minutes), pad2(count.seconds)] : ['–', '––', '––', '––'];
    return (
        <Box role="timer" aria-label={t('hero.timerLabel')} sx={{ display: 'flex', gap: { xs: 1, sm: 2.5 }, justifyContent: 'center', flexWrap: 'wrap', mt: 1 }}>
            {['days', 'hours', 'minutes', 'seconds'].map((u, i) => (
                <Box key={u} sx={{ minWidth: { xs: 72, sm: 120 }, pt: 1.6, pb: 1.2, borderTop: `1px solid ${C.line}`, display: 'grid', gap: 0.3 }}>
                    <Box component="b" sx={{ fontFamily: DISPLAY, fontWeight: 400, fontSize: { xs: 42, sm: 72 }, lineHeight: 1, fontVariantNumeric: 'tabular-nums', color: C.goldHi, textShadow: '0 0 30px rgba(232,196,106,.35)' }}>{units[i]}</Box>
                    <Box component="span" sx={{ fontSize: 11, letterSpacing: '.22em', 'html[dir="rtl"] &': { letterSpacing: 0 }, textTransform: 'uppercase', color: C.mist }}>{t(`hero.units.${u}`)}</Box>
                </Box>
            ))}
        </Box>
    );
}

function Nights({ t, litAll }) {
    const [sel, setSel] = useState(1);
    const refs = useRef([]);
    const special = t('nights.special', { returnObjects: true }) || {};
    const info = (n) => {
        if (special[n]) return special[n];
        if (n > 20 && n % 2) return t('nights.oddLast', { returnObjects: true });
        if (n > 20) return t('nights.last', { returnObjects: true });
        if (n > 10) return t('nights.middle', { returnObjects: true });
        return t('nights.first', { returnObjects: true });
    };
    const cur = info(sel);
    const move = (n) => { setSel(n); refs.current[n - 1]?.focus(); };
    return (
        <>
            <Box sx={{ overflowX: 'auto', pb: 0.75, scrollbarWidth: 'thin' }}>
                <Box role="tablist" aria-label={t('nights.tabs')} sx={{
                    display: 'grid', gridTemplateColumns: 'repeat(30, minmax(30px, 1fr))', gap: 0.5, minWidth: 960, position: 'relative', pt: 2,
                    '&::before': { content: '""', position: 'absolute', insetInline: 0, top: 4, height: 30, borderTop: `1px solid ${C.line}`, borderRadius: '50% / 0 0 100% 100%' },
                }}>
                    {Array.from({ length: 30 }, (_, i) => {
                        const n = i + 1, last = n > 20, odd = last && n % 2, on = sel === n, lit = last || litAll;
                        return (
                            <Box key={n} component="button" type="button" role="tab" aria-selected={on} tabIndex={on ? 0 : -1}
                                aria-label={t('nights.night', { n })} ref={(el) => { refs.current[i] = el; }}
                                onClick={() => setSel(n)}
                                onKeyDown={(e) => {
                                    const fwd = document.documentElement.dir === 'rtl' ? 'ArrowLeft' : 'ArrowRight';
                                    const back = fwd === 'ArrowRight' ? 'ArrowLeft' : 'ArrowRight';
                                    if (e.key === fwd && n < 30) move(n + 1);
                                    if (e.key === back && n > 1) move(n - 1);
                                }}
                                sx={{ appearance: 'none', background: 'none', border: 0, color: 'inherit', cursor: 'pointer', display: 'grid', justifyItems: 'center', gap: 0.75, p: 0, pb: 0.5, minHeight: 48, font: 'inherit',
                                    '&:focus-visible': { outline: `2px solid ${C.goldHi}`, outlineOffset: 3, borderRadius: 1 } }}>
                                <Box component="i" sx={{ display: 'block', width: 2, bgcolor: C.line, height: 10 + Math.round(Math.sin(((n - 0.5) / 30) * Math.PI) * 22) }} />
                                <Box sx={{
                                    width: 20, height: 30, borderRadius: '9px 9px 5px 5px', position: 'relative', transition: 'background .5s, box-shadow .5s, transform .3s',
                                    transitionDelay: litAll && !last ? `${i * 70}ms` : '0ms', transform: on ? 'scale(1.25)' : 'none',
                                    border: `1px solid ${odd ? C.goldHi : 'rgba(232,196,106,.35)'}`,
                                    background: lit ? `radial-gradient(circle at 50% 55%, ${C.goldHi}, ${C.gold} 55%, #9A6A1C)` : '#2B2A44',
                                    boxShadow: lit ? '0 0 18px rgba(232,196,106,.7)' : 'none',
                                    '&::before': { content: '""', position: 'absolute', left: '50%', top: -5, width: 10, height: 5, transform: 'translateX(-50%)', bgcolor: C.gold, borderRadius: '3px 3px 0 0', opacity: 0.7 },
                                }} />
                                <Box component="small" sx={{ fontSize: 11, color: on ? C.goldHi : C.mist, fontVariantNumeric: 'tabular-nums' }}>{n}</Box>
                            </Box>
                        );
                    })}
                </Box>
            </Box>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 2.5, mt: 1.75, fontSize: 13, color: C.mist }}>
                <Box component="span" sx={{ display: 'inline-flex', alignItems: 'center', gap: 1 }}><Box component="i" sx={{ width: 9, height: 13, borderRadius: 1, bgcolor: C.gold, boxShadow: `0 0 8px ${C.gold}` }} />{t('nights.legendLast')}</Box>
                <Box component="span" sx={{ display: 'inline-flex', alignItems: 'center', gap: 1 }}><Box component="i" sx={{ width: 9, height: 13, borderRadius: 1, bgcolor: '#2B2A44', border: `1px solid ${C.goldHi}` }} />{t('nights.legendOdd')}</Box>
            </Box>
            <Box role="tabpanel" aria-live="polite" sx={{
                mt: 3.5, display: 'grid', gridTemplateColumns: { xs: '1fr', md: 'auto 1fr' }, gap: { xs: 2, md: 3.5 }, p: { xs: 2.5, md: 3.5 },
                border: `1px solid ${C.line}`, borderRadius: '22px', background: 'linear-gradient(180deg, rgba(13,22,56,.75), rgba(6,10,31,.6))', backdropFilter: 'blur(6px)',
            }}>
                <Box sx={{ fontFamily: DISPLAY, fontSize: 64, lineHeight: 0.9, color: C.goldHi, minWidth: '2ch', textAlign: { md: 'center' }, fontVariantNumeric: 'tabular-nums' }}>
                    {sel}
                    <Box component="small" sx={{ display: 'block', fontFamily: 'inherit', fontSize: 11, letterSpacing: '.22em', textTransform: 'uppercase', color: C.mist, mt: 1 }}>{t('nights.nightWord')}</Box>
                </Box>
                <Box sx={{ minWidth: 0 }}>
                    <Typography component="h3" sx={{ fontFamily: DISPLAY, fontSize: 26, mb: 0.75, color: C.ivory }}>{cur.title}</Typography>
                    <Typography sx={{ color: C.mist, maxWidth: '60ch' }}>{cur.text}</Typography>
                    {cur.ar && <Ar sx={{ fontSize: 24, mt: 1.25 }}>{cur.ar}</Ar>}
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1.75 }}>
                        {(cur.tags || []).map((x) => <Box key={x} component="span" sx={{ fontSize: 12, px: 1.4, py: 0.5, borderRadius: 99, border: `1px solid ${C.line}`, color: C.goldHi }}>{x}</Box>)}
                    </Box>
                </Box>
            </Box>
        </>
    );
}

function PhoneDay({ t }) {
    const [left, setLeft] = useState('');
    useEffect(() => {
        const tick = () => {
            const now = new Date(), at = new Date(now); at.setHours(17, 42, 0, 0);
            if (at < now) at.setDate(at.getDate() + 1);
            const m = Math.round((at - now) / 6e4);
            setLeft(`${Math.floor(m / 60)}h ${pad2(m % 60)}m`);
        };
        tick(); const id = setInterval(tick, 30000); return () => clearInterval(id);
    }, []);
    const card = { borderRadius: '20px', p: 2, bgcolor: 'rgba(6,10,31,.55)', border: '1px solid rgba(232,196,106,.3)', backdropFilter: 'blur(8px)' };
    const lbl = { fontSize: 11, letterSpacing: '.2em', 'html[dir="rtl"] &': { letterSpacing: 0 }, textTransform: 'uppercase', color: C.mist };
    const big = { fontFamily: DISPLAY, color: C.goldHi, fontVariantNumeric: 'tabular-nums', lineHeight: 1.1 };
    return (
        <Box aria-hidden sx={{ justifySelf: 'center', width: 'min(300px, 100%)', aspectRatio: '9 / 18.5', borderRadius: '44px', p: 1.5,
            background: 'linear-gradient(160deg, #2A2C44, #0C0F22)', boxShadow: '0 30px 80px rgba(0,0,0,.6), inset 0 0 0 1px rgba(255,255,255,.08)' }}>
            <Box sx={{ height: '100%', borderRadius: '34px', overflow: 'hidden', background: 'linear-gradient(180deg, #141F52 0%, #3B2A5C 55%, #C9875A 100%)', pt: 5.5, px: 2.25, pb: 2.25, display: 'flex', flexDirection: 'column', gap: 1.5, color: C.ivory }}>
                <Box sx={{ ...lbl, color: C.goldHi }}>{t('day.phone.day')}</Box>
                <Box sx={{ fontFamily: DISPLAY, fontSize: 22 }}>{t('day.phone.city')}</Box>
                <Box sx={card}>
                    <Box sx={lbl}>{t('day.phone.iftarIn')}</Box>
                    <Box sx={{ ...big, fontSize: 34 }}>{left}</Box>
                    <Box sx={{ height: 6, borderRadius: 6, bgcolor: 'rgba(255,255,255,.12)', overflow: 'hidden', mt: 1.25 }}><Box sx={{ height: '100%', width: '62%', background: `linear-gradient(90deg, ${C.gold}, ${C.goldHi})` }} /></Box>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', fontSize: 13, mt: 1, fontVariantNumeric: 'tabular-nums' }}><span>{t('day.phone.suhoor')}</span><span>{t('day.phone.iftar')}</span></Box>
                </Box>
                <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1.25 }}>
                    <Box sx={{ ...card, p: 1.5 }}><Box sx={lbl}>{t('day.phone.fasts')}</Box><Box sx={{ ...big, fontSize: 22 }}>13 / 30</Box></Box>
                    <Box sx={{ ...card, p: 1.5 }}><Box sx={lbl}>{t('day.phone.khatm')}</Box><Box sx={{ ...big, fontSize: 22 }}>{t('day.phone.juz')}</Box></Box>
                </Box>
                <Box sx={card}>
                    <Box sx={lbl}>{t('day.phone.dua')}</Box>
                    <Ar sx={{ fontSize: 19, color: C.goldHi, mt: 0.75 }}>رَبَّنَا تَقَبَّلْ مِنَّا</Ar>
                    <Box sx={{ fontSize: 12, color: C.mist }}>{t('day.phone.duaMeaning')}</Box>
                </Box>
            </Box>
        </Box>
    );
}

function Remind({ t, i18n }) {
    const [email, setEmail] = useState('');
    const [consent, setConsent] = useState(false);
    const [trap, setTrap] = useState('');
    const [state, setState] = useState({ phase: 'idle', error: null });
    const submit = async (e) => {
        e.preventDefault();
        if (!/^\S+@\S+\.\S+$/.test(email)) return setState({ phase: 'idle', error: t('remind.badEmail') });
        if (!consent) return setState({ phase: 'idle', error: t('remind.needConsent') });
        setState({ phase: 'sending', error: null });
        try {
            await subscribeToNewsletter(
                { email, consent, topics: ['ramadan'], website2: trap, source: '/ramadan', locale: (i18n.language || 'en').slice(0, 2) },
                { rateMessage: t('remind.rate'), errorMessage: t('remind.error') },
            );
            setState({ phase: 'done', error: null });
        } catch (err) {
            setState({ phase: 'idle', error: err.message || t('remind.error') });
        }
    };
    const field = { width: '100%', minHeight: 52, px: 2.25, borderRadius: 99, border: `1px solid ${C.line}`, bgcolor: 'rgba(6,10,31,.6)', color: C.ivory, font: 'inherit', fontSize: 16,
        '&::placeholder': { color: C.mist }, '&:focus-visible': { outline: `2px solid ${C.goldHi}`, outlineOffset: 2 } };
    return (
        <Box id="remind" sx={{ scrollMarginTop: 24, maxWidth: 720, mx: 'auto', textAlign: 'center', p: { xs: 3, md: 5 }, borderRadius: '28px', border: `1px solid ${C.line}`,
            background: 'radial-gradient(120% 120% at 50% 0%, rgba(232,196,106,.16), transparent 60%), rgba(6,10,31,.55)', backdropFilter: 'blur(8px)', display: 'grid', gap: 2, justifyItems: 'center' }}>
            <Box sx={{ width: 64 }}><MoonCanvas phase={0.11} halo={false} label="" /></Box>
            <Eyebrow>{t('remind.eyebrow')}</Eyebrow>
            <H2 id="remind-h">{t('remind.h2')}</H2>
            <Typography sx={{ color: C.mist, maxWidth: 520 }}>{t('remind.lede')}</Typography>
            {state.phase === 'done' ? (
                <Box role="status" sx={{ mt: 1, px: 3, py: 2, borderRadius: 99, border: `1px solid ${C.gold}`, color: C.goldHi, fontWeight: 600 }}>{t('remind.done')}</Box>
            ) : (
                <Box component="form" onSubmit={submit} noValidate aria-labelledby="remind-h" sx={{ width: '100%', display: 'grid', gap: 1.5, mt: 1 }}>
                    <Box sx={{ display: 'flex', gap: 1.25, flexDirection: { xs: 'column', sm: 'row' } }}>
                        <Box component="label" htmlFor="ramadan-email" sx={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(0 0 0 0)' }}>{t('remind.emailLabel')}</Box>
                        <Box component="input" id="ramadan-email" type="email" autoComplete="email" inputMode="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder={t('remind.placeholder')} sx={field} />
                        <Box component="button" type="submit" disabled={state.phase === 'sending'} sx={{
                            minHeight: 52, px: 3.5, borderRadius: 99, border: 0, cursor: 'pointer', font: 'inherit', fontWeight: 700, fontSize: 16, whiteSpace: 'nowrap',
                            bgcolor: C.gold, color: C.sky, '&:hover': { bgcolor: C.goldHi }, '&:disabled': { opacity: 0.6, cursor: 'default' },
                            '&:focus-visible': { outline: `2px solid ${C.goldHi}`, outlineOffset: 3 },
                        }}>{state.phase === 'sending' ? t('remind.sending') : t('remind.cta')}</Box>
                    </Box>
                    <Box component="input" type="text" name="website2" tabIndex={-1} autoComplete="off" value={trap} onChange={(e) => setTrap(e.target.value)} aria-hidden sx={{ position: 'absolute', left: -9999, width: 1, height: 1 }} />
                    <Box component="label" sx={{ display: 'flex', gap: 1.25, alignItems: 'flex-start', textAlign: 'start', fontSize: 14, color: C.mist, cursor: 'pointer', minHeight: 44 }}>
                        <Box component="input" type="checkbox" id="ramadan-consent" checked={consent} onChange={(e) => setConsent(e.target.checked)} sx={{ width: 20, height: 20, mt: '2px', accentColor: C.gold, flexShrink: 0 }} />
                        <span>{t('remind.consent')}</span>
                    </Box>
                    {state.error && <Typography role="alert" sx={{ color: '#FFB4A2', fontSize: 14 }}>{state.error}</Typography>}
                </Box>
            )}
        </Box>
    );
}

export default function RamadanPage() {
    const { t, i18n } = useTranslation('ramadan');
    const { hash } = useLocation();
    const count = useRamadanCountdown();
    const [first, setFirst] = useState(false);
    const [phaseOverride, setPhaseOverride] = useState(null);
    const [mubarak, setMubarak] = useState(false);

    useEffect(() => {
        if (hash === '#remind') setTimeout(() => document.getElementById('remind')?.scrollIntoView({ behavior: reduceMotion() ? 'auto' : 'smooth' }), 300);
    }, [hash]);

    const phase = phaseOverride ?? (count ? moonPhase(count.now) : 0.25);
    const caption = phaseOverride != null
        ? t('hero.crescent')
        : t('hero.tonight', { phase: t(`phases.${moonPhaseKey(phase)}`), lit: moonIllumination(phase) });

    const playFirstNight = () => {
        if (first) return;
        setFirst(true);
        const from = moonPhase(), to = 1.06, start = performance.now(), dur = reduceMotion() ? 1 : 2200;
        const step = (now) => {
            const k = Math.min(1, (now - start) / dur), e = 1 - (1 - k) ** 3;
            setPhaseOverride((from + (to - from) * e) % 1);
            if (k < 1) requestAnimationFrame(step);
            else { setMubarak(true); setTimeout(() => { setMubarak(false); setFirst(false); setPhaseOverride(null); }, 4200); }
        };
        requestAnimationFrame(step);
    };

    const waves = t('waves.items', { returnObjects: true });
    const points = t('day.points', { returnObjects: true });
    const begunDay = count?.begun ? Math.floor((count.now - FIRST_NIGHT().getTime()) / 864e5) + 1 : null;

    return (
        <Box sx={{ width: '100vw', position: 'relative', marginInline: 'calc(50% - 50vw)', mt: -4, mb: -4, overflowX: 'clip', color: C.ivory, bgcolor: C.sky,
            fontFamily: '"Figtree", "Avenir Next", system-ui, sans-serif' }}>
            <Stars warm={first} />

            {/* Hero: tonight's moon and the count */}
            <Box component="header" sx={{ position: 'relative', display: 'grid', justifyItems: 'center', textAlign: 'center', gap: 2.25, px: 'max(16px, env(safe-area-inset-left, 0px))', pt: { xs: 6, md: 8 }, pb: 4 }}>
                <Ar sx={{ fontSize: 22, opacity: 0.85 }}>بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ</Ar>
                <Box sx={{ width: 'min(300px, 70vw)' }}><MoonCanvas phase={phase} label={caption} /></Box>
                <Typography sx={{ fontSize: 13, color: C.mist }}>{caption}</Typography>
                <Typography component="h1" sx={{ fontFamily: DISPLAY, fontSize: { xs: 44, md: 72 }, lineHeight: 1.05, textWrap: 'balance' }}>
                    <Ar sx={{ display: 'block', fontSize: '.62em', mb: 0.75 }}>رَمَضَان ١٤٤٨</Ar>
                    {begunDay ? t('hero.h1Begun') : t('hero.h1')}
                </Typography>
                <Typography sx={{ maxWidth: 560, color: C.mist, fontSize: 18 }}>{begunDay ? t('hero.ledeBegun', { day: begunDay }) : t('hero.lede')}</Typography>
                {!begunDay && <Countdown count={count} t={t} />}
                <Typography sx={{ fontSize: 14, color: C.mist, maxWidth: 520 }}>{t('hero.until')}</Typography>
                <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', justifyContent: 'center' }}>
                    <Box component="a" href="#remind" onClick={(e) => { e.preventDefault(); document.getElementById('remind')?.scrollIntoView({ behavior: reduceMotion() ? 'auto' : 'smooth' }); }}
                        sx={{ minHeight: 48, px: 3, display: 'inline-flex', alignItems: 'center', borderRadius: 99, bgcolor: C.gold, color: C.sky, fontWeight: 700, textDecoration: 'none', '&:hover': { bgcolor: C.goldHi } }}>{t('hero.remind')}</Box>
                    <Box component="button" type="button" onClick={playFirstNight} sx={{ minHeight: 48, px: 3, borderRadius: 99, border: `1px solid ${C.gold}`, bgcolor: 'transparent', color: C.goldHi, font: 'inherit', fontWeight: 600, cursor: 'pointer', '&:hover': { bgcolor: 'rgba(232,196,106,.12)' } }}>{t('hero.firstNight')}</Box>
                </Box>
            </Box>

            <Section aria-labelledby="nights-h">
                <Box sx={{ display: 'grid', gap: 1.25, maxWidth: 640, mb: 3.5 }}>
                    <Eyebrow>{t('nights.eyebrow')}</Eyebrow>
                    <H2 id="nights-h">{t('nights.h2')}</H2>
                    <Typography sx={{ color: C.mist }}>{t('nights.lede')}</Typography>
                </Box>
                <Nights t={t} litAll={first} />
            </Section>

            <Section aria-labelledby="day-h">
                <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: 'minmax(0,1fr) minmax(0,1fr)' }, gap: 6, alignItems: 'center' }}>
                    <PhoneDay t={t} />
                    <Box sx={{ display: 'grid', gap: 2.25 }}>
                        <Box sx={{ display: 'grid', gap: 1.25 }}><Eyebrow>{t('day.eyebrow')}</Eyebrow><H2 id="day-h">{t('day.h2')}</H2></Box>
                        {points.map((p) => (
                            <Box key={p.b} sx={{ display: 'grid', gap: 0.25, paddingInlineStart: 2.25, borderInlineStart: `1px solid ${C.line}` }}>
                                <Typography sx={{ fontFamily: DISPLAY, fontSize: 20 }}>{p.b}</Typography>
                                <Typography sx={{ color: C.mist }}>{p.t}</Typography>
                            </Box>
                        ))}
                    </Box>
                </Box>
            </Section>

            <Section aria-labelledby="waves-h">
                <Box sx={{ display: 'grid', gap: 1.25, maxWidth: 640, mb: 3.5 }}>
                    <Eyebrow>{t('waves.eyebrow')}</Eyebrow>
                    <H2 id="waves-h">{t('waves.h2')}</H2>
                    <Typography sx={{ color: C.mist }}>{t('waves.lede')}</Typography>
                </Box>
                <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: 'repeat(3, minmax(0,1fr))' }, gap: 2.25 }}>
                    {waves.map((w, i) => (
                        <Box key={w.h3} sx={{ p: 3, borderRadius: '22px', border: `1px solid ${C.line}`, bgcolor: C.panel, display: 'grid', gap: 1.75, alignContent: 'start' }}>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 1 }}>
                                <Box aria-hidden sx={{ display: 'flex', gap: 0.6 }}>{[0, 1, 2].map((d) => <Box key={d} sx={{ width: 10, height: 10, borderRadius: '50%', border: `1px solid ${C.gold}`, bgcolor: d <= i ? C.gold : 'transparent' }} />)}</Box>
                                <Box component="em" sx={{ fontStyle: 'normal', fontSize: 12, color: C.mist }}>{w.when}</Box>
                            </Box>
                            <Typography component="h3" sx={{ fontFamily: DISPLAY, fontSize: 24 }}>{w.h3}</Typography>
                            <Box component="ul" sx={{ listStyle: 'none', m: 0, p: 0, display: 'grid', gap: 1.5 }}>
                                {w.items.map((it) => (
                                    <Box component="li" key={it.b} sx={{ display: 'grid', gap: 0.1 }}>
                                        <Box component="b" sx={{ fontWeight: 600, fontSize: 15 }}>{it.b}</Box>
                                        <Box component="span" sx={{ fontSize: 14, color: C.mist }}>{it.t}</Box>
                                    </Box>
                                ))}
                            </Box>
                        </Box>
                    ))}
                </Box>
                <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', mt: 3.5 }}>
                    <Box component={RouterLink} to="/mobile-app/" sx={{ minHeight: 48, px: 3, display: 'inline-flex', alignItems: 'center', borderRadius: 99, bgcolor: C.gold, color: C.sky, fontWeight: 700, textDecoration: 'none', '&:hover': { bgcolor: C.goldHi } }}>{t('waves.getApp')}</Box>
                    <Box component="a" href="/ramadan/2027/" sx={{ minHeight: 48, px: 3, display: 'inline-flex', alignItems: 'center', borderRadius: 99, border: `1px solid ${C.gold}`, color: C.goldHi, fontWeight: 600, textDecoration: 'none', '&:hover': { bgcolor: 'rgba(232,196,106,.12)' } }}>{t('waves.cities')}</Box>
                </Box>
            </Section>

            <Section aria-labelledby="remind-h"><Remind t={t} i18n={i18n} /></Section>

            <Box component="footer" sx={{ position: 'relative', textAlign: 'center', color: C.mist, fontSize: 13, display: 'grid', gap: 1, justifyItems: 'center', px: 2, pt: 2, pb: 8 }}>
                <Ar sx={{ fontSize: 28 }}>اللَّهُمَّ بَلِّغْنَا رَمَضَان</Ar>
                <Typography sx={{ color: C.mist }}>{t('footer.dua')}</Typography>
                <Typography sx={{ color: C.mist, fontSize: 13 }}>{t('footer.note')}</Typography>
            </Box>

            <Box aria-hidden={!mubarak} sx={{ position: 'fixed', inset: 0, zIndex: 1300, display: 'grid', placeItems: 'center', pointerEvents: 'none', opacity: mubarak ? 1 : 0, transition: 'opacity 1.2s' }}>
                <Box sx={{ textAlign: 'center', px: 4.5, py: 3.5, mx: 2, borderRadius: '26px', bgcolor: 'rgba(6,10,31,.78)', border: `1px solid ${C.line}`, backdropFilter: 'blur(10px)' }}>
                    <Ar sx={{ fontSize: { xs: 40, md: 70 }, color: C.goldHi, textShadow: '0 0 40px rgba(232,196,106,.6)' }}>رَمَضَان مُبَارَك</Ar>
                    <Typography sx={{ color: C.mist }}>{t('hero.mubarak')}</Typography>
                </Box>
            </Box>
        </Box>
    );
}
